    await ui.sortBy(pg_uma, "due-total");
    expect(await ui.personOrder(pg_uma)).toEqual([p_ben, p_ada, p_dot, p_cam]);
    expect(await ui.hold(pg_uma, p_dot, {"from": "2026-03-01"})).toBe(true);
    expect(await ui.personOrder(pg_uma)).toEqual([p_dot, p_ben, p_ada, p_cam]);
    await ui.setSetting(pg_uma, "cap", "1.50");
    expect(await ui.personOrder(pg_uma)).toEqual([p_dot, p_ada, p_ben, p_cam]);
    await ui.setSetting(pg_uma, "cap", "");
    const pg_vic = await ui.userPage(browser, "vic", sheet);
    expect(await ui.personOrder(pg_vic)).toEqual([p_cam, p_ada, p_ben, p_dot]);
    await ui.refresh(pg_uma);
    expect(await ui.personOrder(pg_uma)).toEqual([p_dot, p_ben, p_ada, p_cam]);
    expect(await ui.bulkOpen(pg_uma, [c_ada_0])).toEqual({ opened: 0, refused: 1 });
