    expect(await ui.editPerson(pg_uma, p_cam, {"grade": "A"})).toBe(true);
    await ui.sortBy(pg_uma, "grade");
    expect(await ui.personOrder(pg_uma)).toEqual([p_cam, p_ada, p_dot, p_ben]);
    await ui.refresh(pg_uma);
    await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("0.00");
    await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("6.00");
